#define BLOB_NUM    20
#define DIST_ALPHA  25.0
#define DIST_SCALE  1.5
#define DIST_THRESH 0.8
#define DIST_EPS    0.01
#define MOTION_EPS  0.5
#define MIN_SIZE    0.025
#define MAX_SIZE    0.075
#define SPEED       0.005
#define SEED        42.0

/// RNG
// A single iteration of Bob Jenkins' One-At-A-Time hashing algorithm.
uint hash( uint x )  {
    x += ( x << 10u );
    x ^= ( x >>  6u );
    x += ( x <<  3u );
    x ^= ( x >> 11u );
    x += ( x << 15u );
    return x;
}

// Construct a float with half-open range [0:1] using low 23 bits.
// All zeroes yields 0.0, all ones yields the next smallest representable value below 1.0.
float floatConstruct( uint m ) {
    const uint ieeeMantissa = 0x007FFFFFu; // binary32 mantissa bitmask
    const uint ieeeOne      = 0x3F800000u; // 1.0 in IEEE binary32
    m &= ieeeMantissa;                     // Keep only mantissa bits (fractional part)
    m |= ieeeOne;                          // Add fractional part to 1.0
    float  f = uintBitsToFloat( m );       // Range [1:2]
    return f - 1.0;                        // Range [0:1]
}

// Pseudo-random value in half-open range [0:1].
float random( float x ) { 
    return floatConstruct(hash(floatBitsToUint(x))); 
}

/// LavaLamp
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord/iResolution.xy * vec2(1., iResolution.y / iResolution.x);

    vec3 col = vec3(0., 1., 0.);

    for (int idx = 0; idx < BLOB_NUM; idx++) {
        float i = float(idx) + 0.5;
        float size = random(i + SEED);
        size = MIN_SIZE + (size * (MAX_SIZE - MIN_SIZE)); // clamp the value

        float motion = sin(iTime * SPEED / size + i);
        motion = motion / sqrt(motion * motion + MOTION_EPS); // smooth square function, lower eps makes the function more square
        motion = motion * 0.5 + 0.5;

        vec2 pos = vec2(i / float(BLOB_NUM), motion) * vec2(1., iResolution.y / iResolution.x);
        float dist = distance(uv, pos);

        col.r += DIST_SCALE - DIST_SCALE / ( 1. + exp(-DIST_ALPHA * (dist - size))); // logistic function, lower ALPHA makes the blobls connect from further away
    }

    col.r = smoothstep(DIST_THRESH - DIST_EPS, DIST_THRESH + DIST_EPS, col.r);
    fragColor = vec4(col, 1.0);
}
